        if(!wantedTrack||typeof track.isLocked!=="function")throw new Error("Actual track-lock evidence unavailable; camera execution refused");
        var lock=track.isLocked();if(!(lock===true||lock===false||lock===0||lock===1)||!!lock!==wantedTrack.locked)throw new Error("Actual track lock changed or unreadable; camera execution refused");
        for(var c=0;c<track.clips.numItems;c++){
          var clip=track.clips[c]; if(!clip.projectItem||!clip.nodeId||!clip.projectItem.nodeId||typeof clip.getSpeed!=="function"||typeof clip.isSpeedReversed!=="function"||typeof clip.projectItem.isSequence!=="function"||typeof clip.getLinkedItems!=="function")throw new Error("Actual source/speed/reverse/nest/link evidence unavailable");
          var speed=clip.getSpeed(),reversed=clip.isSpeedReversed(),nested=clip.projectItem.isSequence();
          if(!(speed===1||speed===100)||!(reversed===false||reversed===0)||!(nested===false||nested===0))throw new Error("Camera source is retimed, reversed, nested or unknown");
          var linked=clip.getLinkedItems(),linkedIds=[];if(linked&&(typeof linked.numItems!=="number"||linked.numItems>256))throw new Error("Linked identities unavailable");
          for(var l=0;linked&&l<linked.numItems;l++){var linkedId=String(linked[l].nodeId);if(linkedId!==String(clip.nodeId))linkedIds.push(linkedId);}linkedIds.sort();
          found.push({clip:clip,id:String(clip.nodeId),source_id:String(clip.projectItem.nodeId),track_id:trackId,start_ticks:String(clip.start.ticks),end_ticks:String(clip.end.ticks),in_ticks:String(clip.inPoint.ticks),out_ticks:String(clip.outPoint.ticks),enabled:!clip.disabled,linked_ids:linkedIds});
        }
