    function verifyLinks(actual,originalIdentity){for(var i=0;i<actual.length;i++){var observed=[];for(var l=0;l<actual[i].linked_ids.length;l++){var nativeId=actual[i].linked_ids[l],originalId=null;for(var j=0;j<actual.length;j++)if(actual[j].id===nativeId)originalId=expected[j].id;if(!originalId)throw new Error("A linked partner is absent from inspected sequence");observed.push(originalIdentity?nativeId:originalId);}observed.sort();if(observed.join("\\n")!==expectedLinks[i].join("\\n"))throw new Error("Actual linked identities changed");}}
